using Aurora.Core;
using System.Numerics;
static class VehicleWorkflowChecks
{
 public static void Run(Action<bool,string> check,Action<Action,string> reject)
 {
  string script="$TYPE VEHICLETYPE_ROAD\n$DESCRIPTION 123\n$DUMPER_DECK_PIVOT 1 2 3\n$LOD1 old.nmf\n$LODDISTANCE1 100\n$LODJOINT1 trailer.nmf\n$PARTICLE_MOVEMENT vehicle_medium -1.2 3 4\n$PARTICLE_MOVEMENT vehicle_heavy 5 6 7\n$LIGHT_FORWARD 1 2 3\nend\n";
  var lods=VehicleLods.Read(script);check(lods.Length==1&&lods[0].Distance==100,"LOD rows pair their model and matching distance without including joint fields");string changed=VehicleLods.Write(script,[new("LOD1","new.nmf",150),new("LOD2","far.nmf",300)]);check(changed.Contains("$LODDISTANCE2 300")&&changed.Contains("$LODJOINT1 trailer.nmf")&&changed.Contains("$DUMPER_DECK_PIVOT 1 2 3")&&changed.Contains("$DESCRIPTION 123"),"task-based settings preserve hidden native descriptions and mechanism data");reject(()=>VehicleLods.Write(script,[new("LOD1","x.nmf",-1)]),"negative LOD distance");
  var points=VehicleSmoke.Read(script);check(points.Length==2&&points[0].Position==new Vector3(-1.2f,3,4),"native movement smoke coordinates parse independently of effect identifiers");changed=VehicleSmoke.Set(script,1,points[1] with{Position=new(1,2,3)});check(VehicleSmoke.Read(changed)[1].Position==new Vector3(1,2,3)&&changed.Contains("$LIGHT_FORWARD 1 2 3")&&VehicleSmoke.Read(changed)[0]==points[0],"smoke point edits preserve the other emitter and native lamps");check(VehicleSmoke.Read(VehicleSmoke.Set(changed,1,null)).Length==1,"remove one smoke emitter");
  string root=Path.Combine(Path.GetTempPath(),"Aurora-audio-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string sound=Path.Combine(root,"custom.ini");File.WriteAllText(sound,"$TEXT sound_horn horn_car1\n$FLOAT wobble 0\n$END\n");string output=Path.Combine(root,"out");Directory.CreateDirectory(output);string withSound=script.Replace("end\n","$SOUND_PARAMS_WORKSHOP custom.ini\nend\n");string exported=VehicleSoundFiles.Export(withSound,root,output);var file=Directory.GetFiles(output).Single();check(exported.Contains("$SOUND_PARAMS_WORKSHOP "+Path.GetFileName(file))&&File.ReadAllText(file)==File.ReadAllText(sound),"custom native sound INI is copied with a portable reference at model export");string packed=VehicleSoundFiles.Map(withSound,r=>"assets/custom.ini");var entries=new Dictionary<string,byte[]>{{"assets/custom.ini",File.ReadAllBytes(sound)}};string project=Path.Combine(root,"audio.aur");AuroraProjectArchive.Write(project,entries);var restored=AuroraProjectArchive.Read(project);check(VehicleSoundFiles.Map(packed,r=>r=="assets/custom.ini"?sound:r).Contains(sound)&&restored["assets/custom.ini"].SequenceEqual(File.ReadAllBytes(sound)),"custom sound INI travels inside the encrypted portable project");File.WriteAllText(Path.Combine(root,"invalid.ini"),"not a sound config");reject(()=>VehicleSoundFiles.Validate(Path.Combine(root,"invalid.ini")),"unrecognized sound INI");}finally{Directory.Delete(root,true);}
 }
}
